 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, BoxGeometry, Mesh } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const region = config.atlasRegion ?? config.intent?.visualSpec?.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;

  const width = 1.1;
  const height = width / aspect;

  const root = new Group();
  root.userData.handlers = {};

  const timelines = [];
  const primitiveCleanups = [];

  const cInk = color(colors.ink);
  const cSurface = color(colors.surface);
  const baseGradient = mix(cInk, cSurface, smoothstep(0.0, 1.0, uv().y));

  const panelGeom = new PlaneGeometry(width, height, 1, 1);
  const panelMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  panelMat.map = baseGradient;
  panelMat.needsUpdate = true;

  const panel = new Mesh(panelGeom, panelMat);
  panel.onBeforeRender = (renderer, scene, camera) => {
    panel.quaternion.copy(camera.quaternion);
  };
  root.add(panel);

  const accentGeom = new BoxGeometry(0.03, height * 0.45, 0.01);
  const accentMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  accentMat.colorNode = color(colors.accent);
  accentMat.needsUpdate = true;
  const accentStrip = new Mesh(accentGeom, accentMat);
  accentStrip.position.set(-width / 2 + 0.06, 0, 0.015);
  panel.add(accentStrip);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find(i => i.role === 'headline') || items[0];
  let textObj = null;
  if (headline && typeof headline.text === 'string') {
    textObj = ctx.fontAtlas.createText(headline.text, {
      fontSize: headline.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left'
    });
    textObj.position.set(-width / 2 + 0.14, 0, 0.02);
    panel.add(textObj);
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      const result = ctx.primitives[p.name](root, p.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') primitiveCleanups.push(result.cleanup);
    }
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
      if (!tex) return;
      if (THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
      const atlasW = tex.image?.width ?? region.w;
      const atlasH = tex.image?.height ?? region.h;
      const offset = vec2(region.x / atlasW, region.y / atlasH);
      const scale = vec2(region.w / atlasW, region.h / atlasH);
      const atlasUV = uv().sub(offset).mul(scale);
      const grain = texture(tex, atlasUV);
      const shaded = mix(baseGradient, grain.rgb, 0.18);
      panelMat.map = shaded;
      panelMat.needsUpdate = true;
      root.userData.grainTexture = tex;
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    timelines.forEach(t => { try { t.kill(); } catch (e) {} });
    primitiveCleanups.forEach(fn => { try { fn(); } catch (e) {} });
    panelGeom.dispose();
    panelMat.dispose();
    accentGeom.dispose();
    accentMat.dispose();
    if (root.userData.grainTexture && root.userData.grainTexture.dispose) {
      root.userData.grainTexture.dispose();
    }
    if (textObj) {
      textObj.traverse(o => {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach(m => m && m.dispose && m.dispose());
          else if (o.material.dispose) o.material.dispose();
        }
      });
    }
    panel.onBeforeRender = () => {};
  };

  return root;
}
